import gallery from './patternGallery.json';

/**
 * Each toggle's example image in the info panel (InfoPanel.tsx), and the vertical
 * position of each row's baseline as a fraction of the image height, for labelling
 * the rows. The data is generated by scripts/src/renderPatternGallery.ts with the
 * images; regenerate it, do not edit it.
 */
export type GalleryEntry = {
  file: string; montage: string; state: string; sensitivity: number; seconds: number;
  lowCutHz: number; highCutHz: number; rows: { label: string; y: number }[];
};

export const PATTERN_GALLERY: Record<string, GalleryEntry> = gallery;
